def choose_move(observation):
    sx, sy = observation.get("self_position", (0, 0))
    ox, oy = observation.get("opponent_position", (0, 0))
    env = observation.get("environment_name", "resource_collection")
    height = observation.get("grid_height", 1)
    width = observation.get("grid_width", 1)

    def move_towards(target_x, target_y):
        dx = 0
        dy = 0
        delta_x = target_x - sx
        delta_y = target_y - sy
        if delta_x > 0:
            dx = 1
        elif delta_x < 0:
            dx = -1
        if delta_y > 0:
            dy = 1
        elif delta_y < 0:
            dy = -1
        return [dx, dy]

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return move_towards(ox, oy)
        corners = [
            [0, 0],
            [0, height - 1],
            [width - 1, 0],
            [width - 1, height - 1],
        ]
        target = max(corners, key=lambda c: abs(c[0] - ox) + abs(c[1] - oy))
        return move_towards(target[0], target[1])
    elif env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or []
        if not targets:
            # No targets, hold position
            return [0, 0]
        best_target = min(targets, key=lambda t: abs(t[0] - sx) + abs(t[1] - sy))
        return move_towards(best_target[0], best_target[1])
    else:
        resources = observation.get("resources") or []
        if not resources:
            # No resources, attack opponent
            return move_towards(ox, oy)
        best_res = min(resources, key=lambda r: abs(r[0] - sx) + abs(r[1] - sy))
        return move_towards(best_res[0], best_res[1])

